<script lang="ts">import type {EditorStore} from '../store.js';import {patchElement,updateDocument} from '../commands.js';import {parseCsv} from '../template/csv.js';import {evaluateTemplate} from '../template/evaluate.js';export let editor:EditorStore;let error='';
async function load(event:Event){try{const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;const parsed=parseCsv(await file.text());editor.execute(updateDocument({template:{...parsed,currentRecord:0}}));error=''}catch(reason){error=reason instanceof Error?reason.message:String(reason)}}
function record(index:number){const template=$editor.document.template;if(template)editor.execute(updateDocument({template:{...template,currentRecord:index}}))}
function map(element:import('../model.js').TextElement|import('../model.js').BarcodeElement|import('../model.js').QrElement,field:string){if(field)editor.execute(patchElement(element.id,element.type==='text'?{text:`{{${field}}}`}:{value:`{{${field}}}`}))}
</script>
<section><h2>Data & templates</h2><label class="upload">Import CSV<input type="file" accept=".csv,text/csv" on:change={load}></label>{#if error}<p class="error">{error}</p>{/if}{#if $editor.document.template}{@const template=$editor.document.template}<p>{template.records.length} records · {template.fields.join(', ')}</p><label>Preview record <input type="range" min="0" max={Math.max(0,template.records.length-1)} value={template.currentRecord} on:input={(e)=>record(+e.currentTarget.value)}></label><dl>{#each template.fields as field}<dt>{field}</dt><dd>{template.records[template.currentRecord]?.[field]??''}</dd>{/each}</dl><h3>Explicit field mapping</h3>{#each $editor.document.elements.filter(e=>e.type==='text'||e.type==='barcode'||e.type==='qr') as element}<label>{element.name}<select on:change={(e)=>map(element,e.currentTarget.value)}><option value="">Choose CSV field</option>{#each template.fields as field}<option value={field}>{field}</option>{/each}</select></label>{/each}<h3>Resolved elements</h3><ul>{#each $editor.document.elements.filter(e=>e.type==='text'||e.type==='barcode'||e.type==='qr') as element}<li>{element.name}: {evaluateTemplate(element.type==='text'?element.text:element.value,{record:template.records[template.currentRecord]??{}})}</li>{/each}</ul>{/if}</section>
<style>section{padding:.75rem;border-top:1px solid #ddd}h2{font-size:.8rem;text-transform:uppercase}.upload{display:inline-block;border:1px solid #bbb;padding:.35rem;border-radius:4px}.upload input{position:absolute;opacity:0;width:1px}dl{display:grid;grid-template-columns:1fr 1fr;font-size:.75rem}dt,dd{margin:0;padding:.15rem}.error{color:#a21}</style>
